/**
 * Midtrans integration — minimal Express server.
 * Generated by midtrans-kit (`midtrans init express`).
 *
 * Run:  npm init -y && npm i express
 *       (add "type": "module" to package.json)
 *       node --env-file=.env server.js
 */
import { createHash, randomBytes } from "node:crypto";
import express from "express";

const isProduction = process.env.MIDTRANS_IS_PRODUCTION === "true";
const SERVER_KEY = process.env.MIDTRANS_SERVER_KEY ?? "";
const CLIENT_KEY = process.env.MIDTRANS_CLIENT_KEY ?? "";

const SNAP_URL = isProduction ? "https://app.midtrans.com" : "https://app.sandbox.midtrans.com";
const API_URL = isProduction ? "https://api.midtrans.com" : "https://api.sandbox.midtrans.com";

if (!SERVER_KEY) {
  console.error("Missing MIDTRANS_SERVER_KEY. Copy .env.example → .env and fill it in.");
  process.exit(1);
}

const authHeader = () => `Basic ${Buffer.from(`${SERVER_KEY}:`).toString("base64")}`;

// ---------------------------------------------------------------------------
// Price catalog — SERVER-SIDE ONLY. The client sends an itemId, never an amount.
// ---------------------------------------------------------------------------
const PRICES = {
  tshirt: { name: "Ambis T-shirt", priceIdr: 50000 },
  stickerpack: { name: "Sticker Pack", priceIdr: 15000 },
  premium: { name: "Premium Membership", priceIdr: 250000 },
};

// ---------------------------------------------------------------------------
// Order ledger — in-memory for the template. Swap for a database in production
// (keep the same rules: register before create, idempotent settle, amounts match).
// ---------------------------------------------------------------------------
const orders = new Map();

function registerOrder({ orderId, itemId, itemName, amountIdr, email }) {
  const order = { orderId, itemId, itemName, amountIdr, email, status: "pending", createdAt: new Date().toISOString() };
  orders.set(orderId, order);
  return order;
}

function settleOrder({ orderId, transactionStatus, fraudStatus, grossAmount, paymentMethod }) {
  const order = orders.get(orderId);
  if (!order) return "unknown"; // notification for an order we never created
  if (order.status !== "pending") return order.status; // idempotent — never settle twice

  let target = "pending";
  if (transactionStatus === "settlement") target = "paid";
  else if (transactionStatus === "capture") target = fraudStatus === "accept" ? "paid" : "pending";
  else if (transactionStatus === "deny" || transactionStatus === "cancel") target = "failed";
  else if (transactionStatus === "expire") target = "expired";

  if (target === "pending") return "pending";
  if (target === "paid" && grossAmount !== undefined && grossAmount !== order.amountIdr) {
    throw new Error(`Amount mismatch for ${orderId}: expected ${order.amountIdr}, got ${grossAmount}`);
  }
  order.status = target;
  if (target === "paid") order.paidAt = new Date().toISOString();
  return target;
}

/** sha512(order_id + status_code + gross_amount + server_key) — gross_amount
 *  must be hashed EXACTLY as received (string "10000.00", not the number). */
function verifySignature({ orderId, statusCode, grossAmount, signatureKey }) {
  const raw = `${orderId}${statusCode}${grossAmount}${SERVER_KEY}`;
  const expected = createHash("sha512").update(raw).digest("hex");
  return expected.toLowerCase() === signatureKey.toLowerCase();
}

// ---------------------------------------------------------------------------
// App
// ---------------------------------------------------------------------------
const app = express();
app.use(express.json());

// Simple checkout page for trying it out
app.get("/", (_req, res) => {
  const items = Object.entries(PRICES)
    .map(([id, p]) => `<li><button onclick="buy('${id}')">${p.name} — Rp ${p.priceIdr.toLocaleString("id-ID")}</button></li>`)
    .join("");
  res.send(`<!doctype html>
    <html><body style="font-family:system-ui;max-width:560px;margin:48px auto">
      <h1>midtrans-kit express demo</h1>
      <ul style="list-style:none;padding:0;display:grid;gap:8px">${items}</ul>
      <p id="status"></p>
      <script>
        async function buy(itemId) {
          document.getElementById('status').textContent = 'Creating payment…';
          const res = await fetch('/api/payment/create', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ itemId }),
          });
          const data = await res.json();
          if (data.redirectUrl) window.location.href = data.redirectUrl;
          else document.getElementById('status').textContent = 'Error: ' + JSON.stringify(data);
        }
      </script>
    </body></html>`);
});

app.post("/api/payment/create", async (req, res) => {
  try {
    const { itemId, customerName, customerEmail, customerPhone } = req.body ?? {};
    const item = PRICES[itemId];
    if (!item) return res.status(400).json({ error: `Unknown item: ${itemId}` });

    const orderId = `SHOP-${Date.now().toString(36).toUpperCase()}-${randomBytes(5).toString("hex").toUpperCase()}`;
    registerOrder({ orderId, itemId, itemName: item.name, amountIdr: item.priceIdr, email: customerEmail });

    const response = await fetch(`${SNAP_URL}/snap/v1/transactions`, {
      method: "POST",
      headers: { "Content-Type": "application/json", Accept: "application/json", Authorization: authHeader() },
      body: JSON.stringify({
        transaction_details: { order_id: orderId, gross_amount: item.priceIdr },
        item_details: [{ id: itemId, price: item.priceIdr, quantity: 1, name: item.name }],
        customer_details: { first_name: customerName, email: customerEmail, phone: customerPhone },
      }),
    });
    const body = await response.json();
    if (!response.ok || !body.token) throw new Error(`Snap create failed: ${JSON.stringify(body)}`);
    res.json({ orderId, token: body.token, redirectUrl: body.redirect_url });
  } catch (error) {
    console.error("[payment/create]", error);
    res.status(500).json({ error: "Failed to create payment" });
  }
});

// Register this path in the Midtrans dashboard as your Payment Notification URL.
app.post("/api/payment/webhook", (req, res) => {
  const n = req.body ?? {};
  const orderId = String(n.order_id ?? "");
  if (!orderId || !n.signature_key) return res.status(400).json({ error: "Malformed notification" });

  if (!verifySignature({ orderId, statusCode: String(n.status_code ?? ""), grossAmount: String(n.gross_amount ?? ""), signatureKey: String(n.signature_key) })) {
    console.warn("[payment/webhook] invalid signature for", orderId);
    return res.status(403).json({ error: "Invalid signature" });
  }

  try {
    const ledger = settleOrder({
      orderId,
      transactionStatus: String(n.transaction_status ?? ""),
      fraudStatus: n.fraud_status ? String(n.fraud_status) : undefined,
      grossAmount: n.gross_amount ? Math.round(Number(n.gross_amount)) : undefined,
      paymentMethod: n.payment_type ? String(n.payment_type) : undefined,
    });
    // 200 even for "unknown" orders so Midtrans stops retrying.
    res.json({ status: "ok", ledger });
  } catch (error) {
    console.error("[payment/webhook] settle failed", orderId, error);
    res.status(500).json({ error: "Settle failed" }); // Midtrans will retry
  }
});

app.get("/api/payment/status", async (req, res) => {
  const orderId = String(req.query.order_id ?? "");
  const order = orders.get(orderId);
  if (!order) return res.status(404).json({ status: "unknown" });

  // Reconcile with Midtrans while pending (webhook backup path)
  if (order.status === "pending") {
    try {
      const response = await fetch(`${API_URL}/v2/${encodeURIComponent(orderId)}/status`, {
        headers: { Accept: "application/json", Authorization: authHeader() },
      });
      if (response.ok) {
        const m = await response.json();
        const ts = m.transaction_status ?? "";
        const done = ts === "settlement" || (ts === "capture" && m.fraud_status === "accept") ||
          ts === "deny" || ts === "cancel" || ts === "expire";
        if (done) {
          settleOrder({
            orderId,
            transactionStatus: ts,
            fraudStatus: m.fraud_status,
            grossAmount: m.gross_amount ? Math.round(Number(m.gross_amount)) : undefined,
            paymentMethod: m.payment_type,
          });
        }
      }
    } catch (error) {
      console.error("[payment/status] reconcile failed", orderId, error);
    }
  }

  const fresh = orders.get(orderId);
  res.json({ order_id: fresh.orderId, item_name: fresh.itemName, amount_idr: fresh.amountIdr, status: fresh.status });
});

const port = Number(process.env.PORT ?? 3000);
app.listen(port, () => {
  console.log(`midtrans-kit express demo → http://localhost:${port}  (${isProduction ? "PRODUCTION" : "sandbox"})`);
  console.log(`Client key: ${CLIENT_KEY || "(not set)"}`);
});
